<script setup lang="ts">
import {computed,nextTick,onMounted,onUnmounted,ref,watch} from 'vue'
import {useAssistant} from '../../entities/assistant/model'
import {useAuth} from '../../entities/auth/model'
import {activeRun,containsCredentialText,authLabel} from '../../shared/interfaces/assistant'
import type {CredentialSummary,AssistantStatus} from '../../shared/interfaces/assistant'
import {datetime} from '../../shared/lib/format'
import {errorMessage} from '../../shared/api/client'
import Icon from '../../shared/ui/Icon.vue'
import ConversationList from './ConversationList.vue'
import ToolActivity from './ToolActivity.vue'
import SecureCredentialsForm from './SecureCredentialsForm.vue'
import ModelAccessCard from './ModelAccessCard.vue'
const props=withDefaults(defineProps<{variant?:'page'|'drawer'}>(),{variant:'page'}),emit=defineEmits<{close:[]}>(),store=useAssistant(),auth=useAuth(),history=ref(false),secure=ref(false),modelOpen=ref(false),messageScroll=ref<HTMLElement|null>(null),composer=ref<HTMLTextAreaElement|null>(null),localError=ref(''),atBottom=ref(true)
const suggestions=['Помоги подключить Телфин','Создай статусы и теги для отдела продаж','Настрой фильтр пропущенных звонков без перезвона','Проверь, что осталось настроить']
const context=computed(()=>[auth.me?.organization.id,auth.me?.user.id].join(':')),statusText=computed(()=>authLabel(store.status?{...store.status,pending_login:null}:null)),hasActive=computed(()=>activeRun(store.currentRun))
function syncScroll(){const box=messageScroll.value;if(box)atBottom.value=box.scrollHeight-box.scrollTop-box.clientHeight<90}
watch(()=>[store.messages.length,store.messages.at(-1)?.text,store.currentRun?.events.length],async()=>{if(atBottom.value){await nextTick();const box=messageScroll.value;if(box)box.scrollTop=box.scrollHeight}})
watch(context,()=>{secure.value=false;modelOpen.value=false;localError.value='';history.value=false},{flush:'sync'})
watch(secure,async value=>{if(!value)return;await nextTick();const box=messageScroll.value,form=box?.querySelector<HTMLElement>('.assistant-secure');if(box&&form)box.scrollTop+=form.getBoundingClientRect().top-box.getBoundingClientRect().top})
watch(modelOpen,async value=>{if(value){await nextTick();if(messageScroll.value)messageScroll.value.scrollTop=0}})
watch(history,value=>{if(value){secure.value=false;modelOpen.value=false}})
function selected(){history.value=false;secure.value=false;modelOpen.value=false;localError.value=''}
function newThread(){secure.value=false;modelOpen.value=false;store.newConversation();history.value=false}

async function send(text=store.draft){localError.value='';if(containsCredentialText(text)){store.draft='';localError.value='Секреты вводятся только в защищённую форму. Сообщение не отправлено.';secure.value=true;return}store.draft=text;const sent=await store.send(text);if(store.authRequired&&store.error)modelOpen.value=true;if(sent){atBottom.value=true;composer.value?.focus()}}
function paste(event:ClipboardEvent){const value=event.clipboardData?.getData('text')||'';if(containsCredentialText(value)){event.preventDefault();localError.value='Для ключей используйте защищённую форму. Вставьте JSON внутри неё.';secure.value=true}}
function keydown(event:KeyboardEvent){if(event.key==='Enter'&&!event.shiftKey&&!event.isComposing){event.preventDefault();if(store.canSend)send()}}
function saved(value:CredentialSummary){store.addedCredential(value);secure.value=false;store.notice='Доступы Телфина добавлены. Они будут доступны помощнику в следующем запросе.'}
function status(value:AssistantStatus){store.adoptStatus(value)}
async function removeCredential(id:string){try{localError.value='';await store.removeCredential(id)}catch(e){localError.value=errorMessage(e)}}
function visibility(){if(!document.hidden)store.initialize()}
onMounted(()=>{store.initialize();document.addEventListener('visibilitychange',visibility)});onUnmounted(()=>document.removeEventListener('visibilitychange',visibility))
</script>
<template><section class="assistant-panel" :class="'assistant-panel-'+variant" aria-label="Помощник настройки"><header class="assistant-panel-header"><div class="assistant-panel-brand"><span class="assistant-symbol"><Icon name="sparkles" :size="21"/></span><div><h2>Помощник настройки</h2><p>{{auth.me?.organization.name}}</p></div></div><div class="assistant-header-actions"><button class="icon-button assistant-history-toggle" aria-label="История диалогов" :aria-expanded="history" @click="history=!history"><Icon name="clock" :size="18"/></button><RouterLink v-if="variant==='drawer'" :to="{path:'/assistant',query:store.conversation?{conversation:store.conversation.id}:{}}" class="icon-button" aria-label="Открыть помощника на весь экран"><Icon name="expand" :size="17"/></RouterLink><button v-if="variant==='drawer'" class="icon-button" aria-label="Закрыть помощника" @click="emit('close')"><Icon name="close" :size="20"/></button></div></header><div class="assistant-layout" :class="{'assistant-show-history':history}"><ConversationList @select="selected"/><div class="assistant-chat"><div class="assistant-chat-toolbar"><button class="assistant-model-toggle" :class="{connected:store.status?.authenticated}" @click="modelOpen=!modelOpen"><span class="assistant-state-dot" :class="store.status?.authenticated?'completed':'interrupted'"></span>{{statusText}}<Icon name="chevron" :size="12"/></button><button class="text-link" :disabled="store.submitting" @click="newThread"><Icon name="plus" :size="13"/>Новый диалог</button></div><div ref="messageScroll" class="assistant-messages" @scroll="syncScroll"><ModelAccessCard v-if="modelOpen" :key="context" @status="status" @close="modelOpen=false"/><p v-if="store.loading" class="assistant-empty-small" role="status">Загружаем диалог…</p><template v-else><div v-if="!store.messages.length&&!store.error" class="assistant-welcome"><span class="assistant-welcome-symbol"><Icon name="sparkles" :size="27"/></span><span class="eyebrow">НАСТРОЙКИ БЕЗ ЛИШНИХ ШАГОВ</span><h3>С чего начнём?</h3><p>Помогу подключить Телфин и настроить рабочее пространство: статусы, теги, фильтры и правила перезвонов.</p><div class="assistant-suggestions"><button v-for="suggestion in suggestions" :key="suggestion" :disabled="store.busy" @click="send(suggestion)"><span>{{suggestion}}</span><Icon name="arrow" :size="15"/></button></div></div><article v-for="message in store.messages" :key="message.id" class="assistant-message" :class="message.role" :data-message-id="message.id"><div class="assistant-message-meta"><span>{{message.role==='user'?'Вы':'Помощник'}}</span><small>{{datetime(message.created_at,auth.me?.organization.timezone)}}</small></div><ToolActivity v-if="message.role==='assistant'&&store.runs.find(r=>r.id===message.run_id)" :run="store.runs.find(r=>r.id===message.run_id)!"/><div v-if="message.text" class="assistant-message-text">{{message.text}}</div><p v-else-if="message.status==='running'" class="assistant-waiting">Помощник работает<span aria-hidden="true">…</span></p></article></template><p v-if="store.reconnecting" class="assistant-inline-notice" role="status">Проверяем состояние задачи после потери связи…</p><p v-if="store.error" class="assistant-error assistant-inline-notice" role="alert">{{store.error}}</p><p v-if="localError" class="assistant-error assistant-inline-notice" role="alert">{{localError}}</p><p v-if="store.notice" class="assistant-inline-notice" role="status">{{store.notice}}</p><SecureCredentialsForm v-if="secure" :key="context" @saved="saved" @close="secure=false"/><div v-if="store.credentials.length" class="assistant-credentials"><h4><Icon name="lock" :size="13"/>Доступы этого диалога</h4><div v-for="credential in store.credentials" :key="credential.id" class="assistant-credential"><label class="checkbox"><input v-model="store.selectedRefs" type="checkbox" :value="credential.id" :disabled="store.busy||Date.parse(credential.expires_at)<=Date.now()&&!store.selectedRefs.includes(credential.id)||store.selectedRefs.length>=8&&!store.selectedRefs.includes(credential.id)"/><span>{{credential.label||'Телфин'}}<small>{{Date.parse(credential.expires_at)<=Date.now()?'Срок истёк':'Временный доступ до '+datetime(credential.expires_at)}}</small></span></label><button class="icon-button" aria-label="Удалить временный доступ" :disabled="store.busy" @click="removeCredential(credential.id)"><Icon name="close" :size="14"/></button></div><p>Удаление доступа из диалога не отключает уже настроенный Телфин.</p></div></div><div class="assistant-composer"><p v-if="store.uncertainSubmit" class="assistant-inline-notice">Результат отправки неизвестен. Повторите отправку с тем же текстом — новая задача не создастся.</p><label class="assistant-composer-label" for="assistant-composer-text">Задача помощнику</label><textarea id="assistant-composer-text" ref="composer" v-model="store.draft" rows="3" maxlength="8000" :readonly="store.submitting||store.uncertainSubmit" placeholder="Например: создай теги для отдела продаж…" aria-label="Задача помощнику" @keydown="keydown" @paste="paste"></textarea><div class="assistant-composer-actions"><button class="assistant-credentials-button" :disabled="store.submitting" @click="secure=!secure"><Icon name="lock" :size="14"/>Добавить доступы</button><span class="assistant-text-count">{{store.draft.length}} / 8000</span><button v-if="hasActive" class="button small" :disabled="store.stopping" @click="store.stop"><Icon name="stop" :size="13"/>{{store.stopping?'Останавливаем…':'Остановить'}}</button><button v-else class="button primary small" :disabled="!store.canSend" @click="send()"><Icon name="arrow" :size="14"/>{{store.submitting?'Отправляем…':'Отправить'}}</button></div><p class="assistant-composer-hint">Ключи вводите через «Добавить доступы» или подключение Codex. Они не попадут в переписку.</p></div></div></div></section></template>
